int background_w_gedf(
                     struct background * pba,
                     double a,
                     double * w_edf,
                     double * dw_over_da_edf,
                     double * integral_edf
                     ){
  double wi, wf, A, B;
  double y, f, exp_y;
  double logacB, logaB;
  double M, log_1_plus_acB, log_aB_plus_acB;

  wi = pba->wi_edf;
  wf = pba->wf_edf;
  A = - wi + wf;
  B = pba->s_a_gedf * (1. + wf);

  /* w(a) = (-wi + wf)/(1 + (ac/a)^(s_a(1+wf))) + wi */
  if (fabs(B) < 1e-14) {
    *w_edf = 0.5 * A + wi;
    *dw_over_da_edf = 0.;
    *integral_edf = 3. * (1. + *w_edf) * log(1./a);
    return _SUCCESS_;
  }

  y = B * (log(pba->ac_gedf) - log(a));
  if (y >= 0.) {
    exp_y = exp(-y);
    f = exp_y/(1. + exp_y);
  }
  else {
    exp_y = exp(y);
    f = 1./(1. + exp_y);
  }

  *w_edf = A * f + wi;
  *dw_over_da_edf = A * B * f * (1. - f) / a;
  // *dw_over_da_edf = -1.* A * B * pow(f,2) * (1. - 1./f) / a;

